def aggregate_monthly(daily_data):
    monthly = defaultdict(int)
    for date_str, downloads in daily_data.items():
        month_key = date_str[:7]
        monthly[month_key] += downloads
    return dict(sorted(monthly.items()))


npm_monthly = aggregate_monthly(npm_daily)
pypi_monthly = aggregate_monthly(pypi_daily)

with open("data/mcp_sdk_downloads.csv", "w", newline="") as f:
    writer = csv.writer(f)
    writer.writerow(["month", "npm_downloads", "pypi_downloads", "total_downloads"])

    all_months = sorted(set(list(npm_monthly.keys()) + list(pypi_monthly.keys())))
    for month in all_months:
        npm_val = npm_monthly.get(month, 0)
        pypi_val = pypi_monthly.get(month, 0)
        writer.writerow([month, npm_val, pypi_val, npm_val + pypi_val])

